export const handleAgentChangeValue = (studioPro: StudioProApi, field: keyof Agent, agent: Agent, documentId: string) => async (
    value: string
): Promise<Agent> => {
    if (field === "userPrompt" || field === "systemPrompt") {
        const updatedAgent = { ...agent, [field]: value };
        const newVariables: Variable[] = await calculateVariables(studioPro, updatedAgent);
        const updatedAgentWithVariables = { ...updatedAgent, variables: newVariables };
        await updateAgentDocument(studioPro, updatedAgentWithVariables, documentId);
        return updatedAgentWithVariables;
    }
    else {
        const updatedAgent = { ...agent, [field]: value }
        await updateAgentDocument(studioPro, updatedAgent, documentId);
        return updatedAgent;
    }
};


export const handleSelectEntity = async (studioPro: StudioProApi, agent: Agent, documentId: string): Promise<Agent | undefined> => {
    const selectorResult: SelectorResult = await studioPro.ui.elementSelectors.selectEntity({ allowNone: true });
    let updatedAgent: Agent | undefined = undefined;
    if (selectorResult.status === 'ok') {
        updatedAgent = { ...agent, entity: selectorResult.selected.module + '.' + selectorResult.selected.name };
    }
    if (selectorResult.status === 'none') {
        updatedAgent = { ...agent, entity: "" };
    }
    if (updatedAgent) {
        const recalculatedVariables = await checkAttributes(studioPro, agent.variables, updatedAgent);
        updatedAgent = { ...updatedAgent, variables: recalculatedVariables };
        await updateAgentDocument(studioPro, updatedAgent, documentId);
    }
    return updatedAgent;
}


